async function seedBooks() {
  try {
    const existingCount = await prisma.book.count();
    if (existingCount >= 50) {
      console.log(`\u{1F4DA} Database already contains ${existingCount} books. Skipping auto-seed.`);
      return;
    }
    console.log("\u{1F4DA} Seeding 50 trending China, Iraq & Kurdistan books into database...");
    for (const book of initialBooks) {
      await prisma.book.upsert({
        where: { slug: book.slug },
        update: { ...book },
        create: { ...book }
      });
    }
    console.log(`\u2705 Successfully seeded/updated 50 books!`);
  } catch (error) {
    console.error("\u274C Error seeding books:", error);
  }
}

