  app.post("/api/admin/business-opportunities", editorOrAdminMiddleware, async (req, res) => {
    try {
      const {
        titleEn,
        titleAr,
        titleZh,
        titleCkb,
        summaryEn,
        summaryAr,
        summaryZh,
        summaryCkb,
        contentEn,
        contentAr,
        contentZh,
        contentCkb,
        category,
        sector,
        investmentValue,
        location,
        coverImage,
        featured,
        order,
        status,
        contactEmail
      } = req.body;
      if (!titleEn) {
        return res.status(400).json({ error: "English title is required" });
      }
      let slug = req.body.slug;
      if (!slug) {
        slug = titleEn.toLowerCase().replace(/[^\w\s-]/g, "").replace(/[\s_-]+/g, "-").replace(/^-+|-+$/g, "");
      }
      const existing = await prisma.businessOpportunity.findUnique({ where: { slug } });
      if (existing) {
        slug = `${slug}-${Date.now().toString(36)}`;
      }
      const opportunity = await prisma.businessOpportunity.create({
        data: {
          slug,
          titleEn,
          titleAr: titleAr || "",
          titleZh: titleZh || "",
          titleCkb: titleCkb || "",
          summaryEn: summaryEn || "",
          summaryAr: summaryAr || "",
          summaryZh: summaryZh || "",
          summaryCkb: summaryCkb || "",
          contentEn: contentEn || "",
          contentAr: contentAr || "",
          contentZh: contentZh || "",
          contentCkb: contentCkb || "",
          category: category || "INVESTMENT",
          sector: sector || "",
          investmentValue: investmentValue || "",
          location: location || "",
          coverImage: coverImage || "",
          featured: Boolean(featured),
          order: typeof order === "number" ? order : parseInt(order, 10) || 0,
          status: status || "OPEN",
          contactEmail: contactEmail || "business@iraqi-chineseagency.com"
        }
      });
      res.status(201).json(opportunity);
    } catch (error) {
      console.error("Error creating business opportunity:", error);
      res.status(500).json({ error: "Server error" });
    }
  });
